-- Mission S1: sapling collection (data-only migration).
--
-- Adds 80 sapling listings under the 'saplings' top across its
-- four subcategories (fruit, forestry, flower, vegetable - 20 each)
-- sold by Green Leaf Nurseries, with size variants, per-acre
-- guidance (agri), care cards, badges and 6-language common names
-- where genuinely used. The two legacy vegetable saplings are
-- folded into the category tree so /shop/c/vegetable shows 22.
--
-- Everything is idempotent: fixed primary keys (spl_* / splv_*),
-- ON CONFLICT DO NOTHING on inserts, and a guarded UPDATE that
-- only touches legacy rows still outside the tree (categoryId
-- NULL). Re-running on a partially applied database is safe.
-- Nursery and category ids are resolved BY SLUG at runtime, so
-- no production cuids are hard-coded; if the 'green-leaf'
-- nursery is absent the INSERT simply matches no rows.

-- 1) Fold the two legacy vegetable saplings into the tree (guarded:
--    only rows with no categoryId yet, so admin edits always win).
UPDATE "Product" SET "categoryId" = (SELECT id FROM "Category" WHERE slug = 'vegetable'), "subCategory" = 'vegetable'
WHERE "nameEn" IN ('Chilli Saplings — Guntur Sannam', 'Tomato Saplings — Arka Abha') AND category = 'saplings' AND "categoryId" IS NULL;

-- 2) The 80 new listings. id is deterministic (spl_<slug>) so the
--    whole statement is re-runnable; categoryId resolves via the
--    subcategory slug (checked under the 'saplings' top) so no
--    production cuids are hard-coded.
INSERT INTO "Product" (id, "nurseryId", category, "categoryId", "nameEn", names, botanical, badges, care, agri, provenance, "priceMin", mrp, stock, hidden, "subCategory", image)
SELECT v.id, n.id, 'saplings', c.id, v."nameEn", v.names::jsonb, v.botanical, v.badges::jsonb, v.care::jsonb, v.agri::jsonb, '{"grownAt":"Hesaraghatta shade houses"}'::jsonb, v."priceMin", v.mrp, v.stock, false, v."subCategory", '/photos/' || v.slug || '.jpg'
