  ('spl_ridge_gourd', 'ridge-gourd', 'Ridge Gourd Seedlings — Green Star', '{"hi":"तोरई के पौधे","te":"బీర నారు","kn":"ಹೀರೆಕಾಯಿ ಸಸಿ","ta":"பீர்க்கங்காய் நாற்று","mr":"टोरी रोपे"}', 'Luffa acutangula', '["20-25 day seedlings","Needs trellis","Monsoon favourite"]', '{"sun":"Full sun","water":"Every 2 days","soil":"Fertile, well-drained","level":"Beginner"}', '{"season":"Summer and Kharif","spacing":"2 m x 1.5 m on trellis","plantsPerAcre":1350,"daysToTransplant":22,"guidance":"Pick young fruits every 3-4 days."}', 99, 229, 28, 'vegetable'),
  ('spl_bitter_gourd', 'bitter-gourd', 'Bitter Gourd Seedlings — Pusa Vishesh', '{"hi":"करेला के पौधे","te":"కాకర నారు","kn":"ಹಾಗಲ ಸಸಿ","ta":"பாகற்காய் நாற்று","mr":"कारले रोपे"}', 'Momordica charantia', '["20-25 day seedlings","Diabetic-kitchen favourite","Summer and Kharif"]', '{"sun":"Full sun","water":"Every 2 days","soil":"Fertile, well-drained","level":"Beginner"}', '{"season":"Summer and Kharif","spacing":"1.5 m x 1 m on trellis","plantsPerAcre":2700,"daysToTransplant":22,"guidance":"Soak root ball before transplant; hates root disturbance."}', 109, 239, 28, 'vegetable'),
  ('spl_cucumber', 'cucumber', 'Cucumber Seedlings — Multistar', '{"hi":"खीरा के पौधे","te":"దోస నారు","kn":"ಸೌತೆಕಾಯಿ ಸಸಿ","ta":"வெள்ளரி நாற்று","mr":"काकडी रोपे"}', 'Cucumis sativus', '["20-25 day seedlings","Parthenocarpic options","Summer crop"]', '{"sun":"Full sun","water":"Every 2 days, keep leaves dry by evening","soil":"Fertile, well-drained","level":"Beginner"}', '{"season":"Summer and Rabi","spacing":"1.5 m x 0.6 m","plantsPerAcre":4490,"daysToTransplant":22,"guidance":"Mulch to keep fruit clean and soil cool."}', 109, 239, 28, 'vegetable'),
  ('spl_ash_gourd', 'ash-gourd', 'Ash Gourd Seedlings — CO-1', '{"hi":"पेठा के पौधे","te":"బూదిద గుండ నారు","kn":"ಬೂದು ಕುಂಬಳ ಸಸಿ","ta":"நீர் பூசணி நாற்று","mr":"कोहळा रोपे"}', 'Benincasa hispida', '["25-30 day seedlings","Stores for months","Kasar and curry uses"]', '{"sun":"Full sun","water":"Every 2 days, generous at fruiting","soil":"Fertile, deep","level":"Beginner"}', '{"season":"Kharif and Rabi","spacing":"3 m x 2 m on ground","plantsPerAcre":675,"daysToTransplant":27,"guidance":"Give each vine 2-3 sq m; fruit needs dry bedding."}', 109, 239, 26, 'vegetable'),
  ('spl_pumpkin', 'pumpkin', 'Pumpkin Seedlings — Arka Suryamukhi', '{"hi":"कद्दू के पौधे","te":"గుమ్మడి నారు","kn":"ಕುಂಬಳ ಸಸಿ","ta":"பரங்கி நாற்று","mr":"भोपळा रोपे"}', 'Cucurbita moschata', '["25-30 day seedlings","Sprawling vines","Long storage"]', '{"sun":"Full sun","water":"Every 2-3 days","soil":"Fertile, deep","level":"Beginner"}', '{"season":"Kharif and summer","spacing":"2 m x 2 m","plantsPerAcre":1010,"daysToTransplant":27,"guidance":"Pinch main vine at 5 nodes to encourage fruiting arms."}', 109, 239, 26, 'vegetable'),
  ('spl_watermelon', 'watermelon', 'Watermelon Seedlings — Sugar Baby', '{"hi":"तरबूज़ के पौधे","te":"దర్బూజ నారు","kn":"ಕಲ್ಲಂಗಡಿ ಸಸಿ","ta":"தர்பூசணி நாற்று","mr":"कलिंगड रोपे"}', 'Citrullus lanatus', '["20-25 day seedlings","8-10 kg fruits","Summer crop"]', '{"sun":"Full sun","water":"Every 2-3 days, reduce near ripening","soil":"Sandy loam, deep","level":"Beginner"}', '{"season":"Summer (Nov-Feb planting)","spacing":"2 m x 1 m","plantsPerAcre":2020,"daysToTransplant":22,"guidance":"Grafted seedlings resist wilt in wet soils."}', 119, 259, 24, 'vegetable'),
  ('spl_chayote', 'chayote', 'Chayote (Seeme Badane) Sapling', '{"kn":"ಸೀಮೆ ಬದನೆ ಸಸಿ","hi":"चायोटे (चौचौ)","ta":"சௌசௌ கொடி"}', 'Sechium edule', '["Perennial vine","Hill crop","Fruits first year"]', '{"sun":"Partial sun to full sun","water":"Every 2 days, loves moisture","soil":"Deep, rich, moist","level":"Some experience"}', '{"season":"Kharif planting","spacing":"3 m x 3 m on trellis","plantsPerAcre":450,"daysToTransplant":45,"guidance":"Build a strong pandal — a full vine covers 10 sq m."}', 149, 329, 20, 'vegetable')
) AS v(id, slug, "nameEn", names, botanical, badges, care, agri, "priceMin", mrp, stock, "subCategory")
JOIN "Nursery" n ON n.slug = 'green-leaf'
JOIN "Category" c ON c.slug = v."subCategory" AND c."parentId" IS NOT NULL
ON CONFLICT (id) DO NOTHING;

